# builder/gen_ch17_p1.py
# -*- coding: utf-8 -*-

exercises = [{'num': 1, 'title': 'Оборачивание ошибок через fmt.Errorf и спецификатор %w', 'task': 'Используйте `fmt.Errorf("failed to process user %d: %w", id, err)` для оборачивания (wrap) ошибки с сохранением контекста и цепочки вызовов.', 'theory': 'В Go 1.13+ спецификатор `%w` внутри `fmt.Errorf` создает обернутую ошибку (Wrapped Error), реализующую скрытый интерфейс `Unwrap() error`. Это позволяет добавлять контекст к ошибке на каждом уровне архитектуры без потери доступа к первопричине (Root Cause).', 'step_by_step': '1. Создадим базовую ошибку базы данных `var ErrDatabaseUnavailable = errors.New("database connection refused")`.\n2. Напишем функцию `processUser(id int) error`, которая вызывает запрос и оборачивает ошибку через `fmt.Errorf("failed to process user %d: %w", id, err)`.\n3. В `main` вызовем функцию и проверим, что `errors.Is(err, ErrDatabaseUnavailable)` возвращает `true`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n)\n\nvar ErrDatabaseUnavailable = errors.New("database connection refused")\n\nfunc queryUser(id int) error {\n\t// Симуляция сбоя подключения к БД\n\treturn ErrDatabaseUnavailable\n}\n\nfunc processUser(id int) error {\n\tif err := queryUser(id); err != nil {\n\t\treturn fmt.Errorf("failed to process user %d: %w", id, err)\n\t}\n\treturn nil\n}\n\nfunc main() {\n\terr := processUser(42)\n\tif err != nil {\n\t\tfmt.Println("Полный текст ошибки:", err)\n\t\tif errors.Is(err, ErrDatabaseUnavailable) {\n\t\t\tfmt.Println("Первопричина: сбой подключения к базе данных")\n\t\t}\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Полный текст ошибки: failed to process user 42: database connection refused\n# Первопричина: сбой подключения к базе данных'}], 'under_the_hood': '`fmt.Errorf` со спецификатором `%w` оборачивает ошибку в структуру `fmt.wrapError`, у которой есть метод `Unwrap() error`, возвращающий исходную ошибку `err`.', 'pitfalls': 'Использование `%v` или `%s` вместо `%w` просто форматирует текст ошибки в строку, безвозвратно уничтожая цепочку `Unwrap()`, делая невозможным вызов `errors.Is` и `errors.As`.', 'bigtech_interview': '**Вопрос с собеседования:** «Когда следует использовать %w, а когда %v при форматировании ошибок?»\n**Ответ:** `%w` используют, когда вызывающий код (клиент пакета) должен иметь возможность программно проверить тип или маркер ошибки через `errors.Is`/`errors.As`. `%v` используют, когда вы хотите скрыть детали реализации и не делать ошибку частью публичного API пакета.'}, {'num': 2, 'title': 'Функция деления и возврат сигнатуры (float64, error)', 'task': 'Напишите функцию деления, которая возвращает `(float64, error)`. При делении на ноль возвращайте `errors.New("division by zero")`.', 'theory': 'Идиоматичный паттерн в Go для функций, способных завершиться сбоем — возвращать пару значений `(T, error)`, где `error` всегда идет последним возвращаемым значением. При успешном выполнении возвращается `(result, nil)`.', 'step_by_step': '1. Создадим функцию `Divide(a, b float64) (float64, error)`.\n2. Проверим `if b == 0` и вернем `0, errors.New("division by zero")`.\n3. При `b != 0` вернем результат деления `a / b, nil`.\n4. В `main` протестируем успешный вызов и деление на ноль.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n)\n\nfunc Divide(a, b float64) (float64, error) {\n\tif b == 0 {\n\t\treturn 0, errors.New("division by zero")\n\t}\n\treturn a / b, nil\n}\n\nfunc main() {\n\tres, err := Divide(10, 2)\n\tif err != nil {\n\t\tfmt.Println("Ошибка:", err)\n\t} else {\n\t\tfmt.Printf("10 / 2 = %.2f\\n", res)\n\t}\n\n\t_, errZero := Divide(10, 0)\n\tif errZero != nil {\n\t\tfmt.Println("Ошибка деления на 0:", errZero)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 10 / 2 = 5.00\n# Ошибка деления на 0: division by zero'}], 'under_the_hood': 'Интерфейс `error` в Go — это встроенный стандартный интерфейс с единственным методом `Error() string`. `errors.New` создает экземпляр структуры `errors.errorString` в памяти кучи.', 'pitfalls': 'Никогда не используйте возвращаемое полезное значение, если `err != nil`. По соглашению в Go, при ошибке полезное значение считается невалидным (zero value).', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Go ошибки возвращаются как значения, а не через исключения (try/catch)?»\n**Ответ:** Возврат ошибок как обычных значений делает поток управления прозрачным, локальным и предсказуемым. Разработчик обязан явно обработать или пробросить ошибку на месте возникновения, что исключает скрытые прыжки по стеку вызовов.'}, {'num': 3, 'title': 'Кастомный тип ошибки AppError с полями Code и Message', 'task': '**Кастомная ошибка**: Создай структуру `AppError` с полями `Code int` и `Message string`. Реализуй для неё метод `Error() string`. Верни её из функции.', 'theory': 'Любая пользовательская структура данных в Go становится ошибкой, если она реализует интерфейс `error`, то есть определяет метод `Error() string`. Это позволяет прикреплять к ошибке любые метаданные (HTTP статус-код, внутренний код ошибки, таймстемп, трассировку).', 'step_by_step': '1. Объявим структуру `AppError` с полями `Code int` и `Message string`.\n2. Реализуем метод `(e *AppError) Error() string`.\n3. Напишем функцию `validateUser(age int) error`, возвращающую `*AppError`.\n4. В `main` вызовем функцию и обработаем ошибку.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\ntype AppError struct {\n\tCode    int\n\tMessage string\n}\n\nfunc (e *AppError) Error() string {\n\treturn fmt.Sprintf("[Error %d] %s", e.Code, e.Message)\n}\n\nfunc validateUser(age int) error {\n\tif age < 18 {\n\t\treturn &AppError{\n\t\t\tCode:    403,\n\t\t\tMessage: "пользователь должен быть совершеннолетним",\n\t\t}\n\t}\n\treturn nil\n}\n\nfunc main() {\n\terr := validateUser(16)\n\tif err != nil {\n\t\tfmt.Println("Получена ошибка:", err.Error())\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Получена ошибка: [Error 403] пользователь должен быть совершеннолетним'}], 'under_the_hood': 'При возврате `&AppError` в интерфейс `error` создается `iface { tab: *itab(AppError), data: *AppError }`. Метод `Error()` вызывается через таблицу методов `itab`.', 'pitfalls': 'Критическая ловушка типизированного nil: если функция возвращает `*AppError` равный `nil`, а сигнатура возврата объявлена как `error`, то `err != nil` вернет `true`! Всегда возвращайте литерал `nil`, если ошибки нет.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему возврат var err *AppError = nil внутри функции с возвращаемым типом error приводит к багу?»\n**Ответ:** Интерфейс `error` считается `nil` только когда оба его внутренних поля `tab` (тип) и `data` (указатель) равны `nil`. Если вернуть типизированный указатель `(*AppError)(nil)`, поле типа `tab` будет заполнено дескриптором `*AppError`, поэтому проверка `if err != nil` ошибочно вернет `true`.'}, {'num': 4, 'title': 'Базовые ошибки: errors.New против fmt.Errorf', 'task': '**Базовые ошибки**: Используй `errors.New("bad input")` и `fmt.Errorf("user %s not found", name)` для создания простых ошибок.', 'theory': '- `errors.New` используется для статических текстовых сообщений, не требующих форматирования.\n- `fmt.Errorf` используется для динамических сообщений с интерполяцией переменных (ID, имена файлов, статусы).', 'step_by_step': '1. Создадим функцию `checkInput(input string) error` со статической ошибкой `errors.New`.\n2. Создадим функцию `findUser(name string) error` с динамической ошибкой `fmt.Errorf`.\n3. В `main` вызовем обе функции и распечатаем результат.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n)\n\nfunc checkInput(input string) error {\n\tif input == "" {\n\t\treturn errors.New("bad input: empty payload")\n\t}\n\treturn nil\n}\n\nfunc findUser(name string) error {\n\t// Симулируем отсутствие пользователя\n\treturn fmt.Errorf("user %q not found in local cache", name)\n}\n\nfunc main() {\n\tif err := checkInput(""); err != nil {\n\t\tfmt.Println("checkInput err:", err)\n\t}\n\n\tif err := findUser("Алексей"); err != nil {\n\t\tfmt.Println("findUser err:  ", err)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# checkInput err: bad input: empty payload\n# findUser err:   user "Алексей" not found in local cache'}], 'under_the_hood': '`errors.New` возвращает указатель `&errorString{s}`. Два вызова `errors.New("err") == errors.New("err")` вернут `false`, так как сравниваются адреса в куче.', 'pitfalls': 'По соглашению Go, текст ошибок должен начинаться со строчной буквы и не заканчиваться точкой (кроме имен собственных и аббревиатур), чтобы при оборачивании текст сливался в читаемую фразу.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Go сообщения об ошибках пишут со строчной буквы?»\n**Ответ:** Потому что ошибки в Go часто оборачиваются в цепочки через `fmt.Errorf("failed to %s: %w", op, err)`. Если бы каждая ошибка начиналась с заглавной буквы, цепочка выглядела бы неаккуратно: `Failed to open: File not found: Permission denied`.'}, {'num': 5, 'title': 'Sentinel-ошибки и проверка через errors.Is', 'task': 'Создайте Sentinel-ошибку `var ErrNotFound = errors.New("not found")`. Используйте `errors.Is(err, ErrNotFound)` для проверки, даже если ошибка была обернута несколько раз.', 'theory': 'Sentinel Error (маркерная ошибка) — это предопределенная переменная на уровне пакета. `errors.Is` рекурсивно разворачивает цепочку ошибок через `Unwrap()`, проверяя, есть ли среди них искомый маркер.', 'step_by_step': '1. Объявим `var ErrNotFound = errors.New("not found")`.\n2. Создадим цепочку из трех функций: `repoFind -> serviceGet -> handlerGet`.\n3. Каждая промежуточная функция оборачивает ошибку через `%w`.\n4. В `main` убедимся, что `errors.Is(err, ErrNotFound)` находит маркер на самом верху.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n)\n\nvar ErrNotFound = errors.New("not found")\n\nfunc repoFind(id int) error {\n\treturn ErrNotFound\n}\n\nfunc serviceGet(id int) error {\n\tif err := repoFind(id); err != nil {\n\t\treturn fmt.Errorf("service error for id %d: %w", id, err)\n\t}\n\treturn nil\n}\n\nfunc handlerGet(id int) error {\n\tif err := serviceGet(id); err != nil {\n\t\treturn fmt.Errorf("handler GET failed: %w", err)\n\t}\n\treturn nil\n}\n\nfunc main() {\n\terr := handlerGet(100)\n\tif err != nil {\n\t\tfmt.Println("Цепочка ошибок:", err)\n\t\tif errors.Is(err, ErrNotFound) {\n\t\t\tfmt.Println("-> Результат: запись успешно опознана как ErrNotFound (HTTP 404)")\n\t\t}\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Цепочка ошибок: handler GET failed: service error for id 100: not found\n# -> Результат: запись успешно опознана как ErrNotFound (HTTP 404)'}], 'under_the_hood': '`errors.Is` проверяет `err == target`, а если не совпало — вызывает метод `Is(error) bool` у структуры ошибки (если он есть) или метод `Unwrap() error`, повторяя поиск по цепочке.', 'pitfalls': 'Не сравнивайте обернутые ошибки через оператор `==`, так как `err == ErrNotFound` вернет `false` для обернутой ошибки.', 'bigtech_interview': '**Вопрос с собеседования:** «Как работает errors.Is под капотом?»\n**Ответ:** 1) Проверяет прямое равенство `err == target`. 2) Проверяет, реализует ли `err` метод `Is(target error) bool`. 3) Если нет, вызывает `Unwrap()` и рекурсивно повторяет алгоритм для внутренней ошибки.'}, {'num': 6, 'title': 'Идиоматичная проверка if err != nil', 'task': 'Вызови функцию `Divide` и проверь ошибку стандартным `if err != nil`.', 'theory': 'В Go проверка `if err != nil` является фундаментальным идиоматичным способом контроля хода программы (Happy Path слева, ошибки обрабатываются сразу).', 'step_by_step': '1. Создадим функцию `SafeDivide(a, b int) (int, error)`.\n2. Вызовем функцию в `main`.\n3. Сразу после вызова напишем `if err != nil` с логированием или возвратом.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n)\n\nfunc SafeDivide(a, b int) (int, error) {\n\tif b == 0 {\n\t\treturn 0, errors.New("cannot divide by zero")\n\t}\n\treturn a / b, nil\n}\n\nfunc main() {\n\tres, err := SafeDivide(40, 0)\n\tif err != nil {\n\t\tfmt.Printf("Обработка сбоя: %v\\n", err)\n\t\treturn\n\t}\n\tfmt.Printf("Результат: %d\\n", res)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Обработка сбоя: cannot divide by zero'}], 'under_the_hood': 'Компилятор Go оптимизирует проверки `if err != nil`, генерируя короткие условные переходы (`TESTQ`/`JNZ`) на ассемблере x86-64.', 'pitfalls': 'Избегайте глубокой вложенности `if err == nil { ... if err2 == nil { ... } }`. Обрабатывайте ошибки первыми (Guard Clause), сохраняя основной поток кода на верхнем уровне отступов.', 'bigtech_interview': '**Вопрос с собеседования:** «Что такое принцип Line of Sight в Go?»\n**Ответ:** Это правило оформления кода, при котором основной успешный путь выполнения («Happy Path») идет ровно по левому краю функции с минимальным уровнем отступов, а ошибки обрабатываются в коротких guard-блоках `if err != nil` с ранним выходом (`return`).'}, {'num': 7, 'title': 'Сравнение sentinel-ошибок: оператор == против errors.Is', 'task': '**Sentinel Errors (Маркерные ошибки)**: Объяви на уровне пакета `var ErrNotFound = errors.New("not found")`. Верни её из функции. В `main` сравни результат строго: `if err == ErrNotFound`.', 'theory': 'Прямое сравнение `err == ErrNotFound` работает только для прямых необернутых ошибок. Как только ошибка будет обернута через `%w`, прямое сравнение вернет `false`.', 'step_by_step': '1. Объявим пакетную переменную `var ErrUserNotFound = errors.New("user not found")`.\n2. Создадим функцию `findDirect(id int) error`, возвращающую `ErrUserNotFound` напрямую.\n3. Продемонстрируем успешное сравнение через `==`.\n4. Покажем, что для обернутой ошибки `==` ломается, а `errors.Is` работает надежно.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n)\n\nvar ErrUserNotFound = errors.New("user not found")\n\nfunc findDirect(id int) error {\n\treturn ErrUserNotFound\n}\n\nfunc findWrapped(id int) error {\n\treturn fmt.Errorf("user service: %w", ErrUserNotFound)\n}\n\nfunc main() {\n\terr1 := findDirect(1)\n\tfmt.Println("findDirect == ErrUserNotFound:", err1 == ErrUserNotFound)\n\n\terr2 := findWrapped(2)\n\tfmt.Println("findWrapped == ErrUserNotFound:", err2 == ErrUserNotFound) // false!\n\tfmt.Println("errors.Is(findWrapped, ErrUserNotFound):", errors.Is(err2, ErrUserNotFound)) // true!\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# findDirect == ErrUserNotFound: true\n# findWrapped == ErrUserNotFound: false\n# errors.Is(findWrapped, ErrUserNotFound): true'}], 'under_the_hood': '`errors.New` выделяет уникальный адрес в памяти. Оператор `==` сравнивает равенство указателей интерфейса `iface.data`.', 'pitfalls': 'В современном коде Go 1.13+ всегда предпочитайте `errors.Is` прямому оператору `==`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Go 1.13+ не рекомендуется использовать if err == ErrNotFound?»\n**Ответ:** Потому что любая внутренняя функция в цепочке вызовов может обернуть ошибку контекстом через `fmt.Errorf("%w")`, после чего прямое сравнение `==` перестанет работать, что приведет к трудноуловимым багам.'}, {'num': 8, 'title': 'Добавление контекста с помощью fmt.Errorf и глагола %v', 'task': 'Используй `fmt.Errorf("reading %s: %v", filename, err)` для добавления контекста. Покажи, что `%v` просто вставляет текст ошибки.', 'theory': 'Спецификатор `%v` преобразует ошибку `err` в строку через вызов `err.Error()`. При этом результирующая ошибка не реализует метод `Unwrap()`, а значит исходная ошибка скрыта.', 'step_by_step': '1. Создадим ошибку `var ErrDiskFailure = errors.New("hardware read error")`.\n2. Обернем её с помощью `%v`: `fmt.Errorf("reading %s: %v", filename, err)`.\n3. В `main` покажем, что `errors.Is` вернет `false`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n)\n\nvar ErrDiskFailure = errors.New("hardware read error")\n\nfunc readFile(filename string) error {\n\t// Добавляем строковый контекст без оборачивания:\n\treturn fmt.Errorf("reading %s: %v", filename, ErrDiskFailure)\n}\n\nfunc main() {\n\terr := readFile("app.json")\n\tfmt.Println("Текст ошибки:", err)\n\n\t// errors.Is не может развернуть %v:\n\tif errors.Is(err, ErrDiskFailure) {\n\t\tfmt.Println("Disk failure detected")\n\t} else {\n\t\tfmt.Println("errors.Is вернул false (цепочка разорвана глаголом %v)")\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Текст ошибки: reading app.json: hardware read error\n# errors.Is вернул false (цепочка разорвана глаголом %v)'}], 'under_the_hood': 'Спецификатор `%v` создает обычную структуру `errors.errorString`, в которую записывается отформатированная строка.', 'pitfalls': 'Если вам нужно сохранить возможность проверки исходной ошибки выше по стеку, используйте `%w` вместо `%v`.', 'bigtech_interview': '**Вопрос с собеседования:** «Когда разрыв цепочки через %v является преимуществом?»\n**Ответ:** Когда нужно скрыть детали реализации внутреннего слоя (Information Hiding). Например, чтобы слой HTTP-контроллеров не зависел от драйвера базы данных PostgreSQL.'}, {'num': 9, 'title': 'Множественные типы ошибок и диспетчеризация через errors.As', 'task': 'Напишите функцию, которая возвращает несколько разных типов ошибок, и корректно обработайте их в `main` с помощью `switch` и `errors.As`.', 'theory': '`errors.As` находит в цепочке ошибку, соответствующую целевому типу структуры/указателя, и копирует значение в переданный указатель. Это безопасный аналог Type Assertion для цепочек ошибок.', 'step_by_step': '1. Объявим кастомные типы ошибок `NetworkTimeoutError` и `InvalidFormatError`.\n2. Напишем функцию `fetchData(url string) error`.\n3. В `main` обработаем ошибки через `switch` с `errors.As`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n)\n\ntype NetworkTimeoutError struct {\n\tURL string\n}\n\nfunc (e *NetworkTimeoutError) Error() string {\n\treturn fmt.Sprintf("network timeout requesting %s", e.URL)\n}\n\ntype InvalidFormatError struct {\n\tLine int\n}\n\nfunc (e *InvalidFormatError) Error() string {\n\treturn fmt.Sprintf("invalid payload format at line %d", e.Line)\n}\n\nfunc fetchData(mode int) error {\n\tswitch mode {\n\tcase 1:\n\t\treturn fmt.Errorf("api gateway: %w", &NetworkTimeoutError{URL: "https://api.internal/v1"})\n\tcase 2:\n\t\treturn fmt.Errorf("parser: %w", &InvalidFormatError{Line: 42})\n\tdefault:\n\t\treturn nil\n\t}\n}\n\nfunc main() {\n\tfor _, mode := range []int{1, 2} {\n\t\terr := fetchData(mode)\n\t\tvar netErr *NetworkTimeoutError\n\t\tvar fmtErr *InvalidFormatError\n\n\t\tswitch {\n\t\tcase errors.As(err, &netErr):\n\t\t\tfmt.Printf("[RETRY] Тайм-аут сети к URL: %s\\n", netErr.URL)\n\t\tcase errors.As(err, &fmtErr):\n\t\t\tfmt.Printf("[REJECT] Ошибка формата на строке: %d\\n", fmtErr.Line)\n\t\tdefault:\n\t\t\tfmt.Println("Успех или неизвестная ошибка")\n\t\t}\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [RETRY] Тайм-аут сети к URL: https://api.internal/v1\n# [REJECT] Ошибка формата на строке: 42'}], 'under_the_hood': '`errors.As` проверяет типы через рефлексию `reflect.TypeOf` и метод `As(target any) bool`, присваивая указатель на найденную структуру.', 'pitfalls': 'Второй аргумент `errors.As` обязан быть указателем на переменную типа ошибки (`&netErr`), иначе возникнет паника в рантайме.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему второй аргумент errors.As должен быть непустым указателем?»\n**Ответ:** `errors.As` должен записать найденное значение ошибки в переменную вызывающего кода. Если передать не указатель или указатель на интерфейс nil, функция запаникует с ошибкой `errors: *target must be interface or implement error`.'}, {'num': 10, 'title': 'Распаковка ошибки через errors.Unwrap (Go 1.13+)', 'task': 'Используй `fmt.Errorf` с глаголом `%w` (Go 1.13+): `fmt.Errorf("processing failed: %w", err)`. Покажи, что ошибка **обёрнута** (wrapped) и сохраняет оригинал.', 'theory': 'Функция `errors.Unwrap(err)` извлекает внутреннюю ошибку ровно на один уровень глубже. Если ошибка не оборачивает другую ошибку, `errors.Unwrap` возвращает `nil`.', 'step_by_step': '1. Создадим базовую ошибку `baseErr := errors.New("connection reset")`.\n2. Обернем её: `wrappedErr := fmt.Errorf("processing failed: %w", baseErr)`.\n3. Извлечем базовую ошибку через `errors.Unwrap(wrappedErr)`.\n4. В `main` убедимся, что распакованная ошибка идентична `baseErr`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n)\n\nfunc main() {\n\tbaseErr := errors.New("connection reset")\n\twrappedErr := fmt.Errorf("processing failed: %w", baseErr)\n\n\tfmt.Println("Обернутая ошибка:  ", wrappedErr)\n\n\tunwrappedErr := errors.Unwrap(wrappedErr)\n\tfmt.Println("Распакованная ошибка:", unwrappedErr)\n\tfmt.Println("unwrappedErr == baseErr:", unwrappedErr == baseErr)\n\n\t// Попытка распаковать базовую ошибку возвращает nil:\n\tfmt.Println("Unwrap(baseErr):", errors.Unwrap(baseErr))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Обернутая ошибка:   processing failed: connection reset\n# Распакованная ошибка: connection reset\n# unwrappedErr == baseErr: true\n# Unwrap(baseErr): <nil>'}], 'under_the_hood': '`errors.Unwrap` проверяет наличие метода `Unwrap() error` у интерфейса `err` и вызывает его.', 'pitfalls': 'Для поиска ошибки в глубине цепочки лучше использовать `errors.Is`/`errors.As`, а не вручную крутить цикл `errors.Unwrap`.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем разница между errors.Unwrap и errors.Is?»\n**Ответ:** `errors.Unwrap` разворачивает ровно один слой обертки. `errors.Is` выполняет полный рекурсивный обход всего дерева/цепочки оберток до совпадения.'}, {'num': 11, 'title': 'Кастомная структура ошибки ValidationError с метаданными полей', 'task': '**Кастомная структура ошибки**: Создайте структуру `ValidationError` с полями `FieldName string` и `Value any`. Реализуйте метод `Error() string` для этой структуры, чтобы она удовлетворяла интерфейсу `error`.', 'theory': 'Кастомные ошибки-структуры позволяют передавать вызывающему коду структурированную контекстную информацию (имя некорректного поля, переданное значение, допустимые границы).', 'step_by_step': '1. Объявим структуру `ValidationError` с полями `FieldName string` и `Value any`.\n2. Реализуем метод `(e ValidationError) Error() string`.\n3. Создадим функцию `validateEmail(email string) error`.\n4. В `main` проверим валидацию.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"strings"\n)\n\ntype ValidationError struct {\n\tFieldName string\n\tValue     any\n}\n\nfunc (e ValidationError) Error() string {\n\treturn fmt.Sprintf("поле %q содержит невалидное значение: %v", e.FieldName, e.Value)\n}\n\nfunc validateEmail(email string) error {\n\tif !strings.Contains(email, "@") {\n\t\treturn ValidationError{\n\t\t\tFieldName: "email",\n\t\t\tValue:     email,\n\t\t}\n\t}\n\treturn nil\n}\n\nfunc main() {\n\terr := validateEmail("invalid-email-address")\n\tif err != nil {\n\t\tfmt.Println("Ошибка валидации:", err)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Ошибка валидации: поле "email" содержит невалидное значение: invalid-email-address'}], 'under_the_hood': 'Поскольку ресивер `(e ValidationError)` объявлен по значению, любая переменная `ValidationError` реализует `error` напрямую.', 'pitfalls': 'Если объявить метод на указателе `(e *ValidationError)`, то передача структуры по значению `ValidationError{}` не будет удовлетворять интерфейсу `error`.', 'bigtech_interview': '**Вопрос с собеседования:** «Когда объявлять метод Error() на указателе (*MyError), а когда на значении (MyError)?»\n**Ответ:** По соглашению в Go метод `Error()` объявляют на указателе `*MyError`, если структура содержит мутируемые поля или для исключения копирования тяжелых структур. Если структура маленькая и иммутабельная (как `time.ParseError`), допустим value receiver.'}, {'num': 12, 'title': 'Обертывание ошибок репозитория с добавлением слоя контекста', 'task': '**Обертывание (Wrapping)**: При получении ошибки в функции (например, от базы данных), не возвращай её как есть. Оберни её: `return fmt.Errorf("failed to get user: %w", err)`.', 'theory': 'Оборачивание ошибок на границах архитектурных слоев (Repository -> Service -> Handler) строит полную трассировку выполнения, объясняя *какая именно операция* завершилась сбоем.', 'step_by_step': '1. Создадим функцию `dbQuery(query string) error`.\n2. Создадим функцию `GetUserByID(id int) error`, которая вызывает `dbQuery` и оборачивает ошибку.\n3. В `main` распечатаем результирующую ошибку.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n)\n\nfunc dbQuery(query string) error {\n\treturn errors.New("connection timeout")\n}\n\nfunc GetUserByID(id int) error {\n\terr := dbQuery("SELECT * FROM users WHERE id = ?")\n\tif err != nil {\n\t\treturn fmt.Errorf("failed to get user %d: %w", id, err)\n\t}\n\treturn nil\n}\n\nfunc main() {\n\terr := GetUserByID(500)\n\tif err != nil {\n\t\tfmt.Println("Случилась ошибка:", err)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Случилась ошибка: failed to get user 500: connection timeout'}], 'under_the_hood': 'Обертка сохраняет ссылку на `err` внутри `fmt.wrapError.err`.', 'pitfalls': 'Не оборачивайте ошибку дважды одной и той же фразой `failed to get user: failed to get user`.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем преимущество цепочек ошибок Go над Java Stacktrace?»\n**Ответ:** Цепочки ошибок в Go содержат только осмысленный бизнес- и системный контекст, добавленный разработчиком, в отличие от тяжелых стектрейсов JVM, замедляющих рантайм на сбор адресов фреймов стека.'}, {'num': 13, 'title': 'Пробитие обертки errors.Is сквозь цепочку вызовов', 'task': '**[Каверзный кейс]**: Оберни ошибку: `fmt.Errorf("db query failed: %w", err)`. Проверь исходную ошибку с помощью `errors.Is` (она "пробьется" через обертку `%w`).', 'theory': 'Спецификатор `%w` формирует односвязный список ошибок. `errors.Is` выполняет линейный проход по цепочке `Unwrap()` до нахождения целевого маркера.', 'step_by_step': '1. Объявим `var ErrNoRows = errors.New("sql: no rows in result set")`.\n2. Создадим функцию `findOrder(id string) error` с тремя уровнями обертывания.\n3. В `main` убедимся, что `errors.Is(err, ErrNoRows)` вернет `true`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n)\n\nvar ErrNoRows = errors.New("sql: no rows in result set")\n\nfunc rawQuery() error {\n\treturn ErrNoRows\n}\n\nfunc findOrder(orderID string) error {\n\tif err := rawQuery(); err != nil {\n\t\treturn fmt.Errorf("db query failed: %w", err)\n\t}\n\treturn nil\n}\n\nfunc main() {\n\terr := findOrder("ord-999")\n\tfmt.Printf("Обернутая ошибка: %v\\n", err)\n\n\tif errors.Is(err, ErrNoRows) {\n\t\tfmt.Println("Успех: ошибка распознана как отсутствие строк (ErrNoRows)")\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Обернутая ошибка: db query failed: sql: no rows in result set\n# Успех: ошибка распознана как отсутствие строк (ErrNoRows)'}], 'under_the_hood': '`errors.Is` рекурсивно проверяет равенство каждого узла в графе оберток.', 'pitfalls': 'Если случайно использовать `%v` вместо `%w` хотя бы на одном звене цепи, `errors.Is` не сможет дойти до исходной ошибки.', 'bigtech_interview': '**Вопрос с собеседования:** «Может ли ошибка в Go содержать несколько предков (дерево ошибок)?»\n**Ответ:** Да! Начиная с Go 1.20, тип ошибки может реализовывать метод `Unwrap() []error` (как в `errors.Join`), формируя дерево ошибок, по которому `errors.Is` осуществляет поиск в глубину (DFS).'}, {'num': 14, 'title': 'Безопасное извлечение ошибки через errors.As', 'task': 'Используйте `errors.As(err, &validationErr)` для безопасного извлечения вашей кастомной ошибки из глубины обернутых ошибок.', 'theory': '`errors.As` заменяет устаревший Type Assertion `err.(MyError)`. В отличие от кастинга, `errors.As` успешно находит ошибку даже внутри многократно обернутой цепочки.', 'step_by_step': '1. Создадим структуру `ValidationError struct { Field string; Code string }`.\n2. Напишем функцию с двукратным оборачиванием ошибки.\n3. В `main` извлечем `ValidationError` через `errors.As`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n)\n\ntype ValidationError struct {\n\tField string\n\tCode  string\n}\n\nfunc (e *ValidationError) Error() string {\n\treturn fmt.Sprintf("validation failed on field %s (code: %s)", e.Field, e.Code)\n}\n\nfunc parsePayload() error {\n\treturn &ValidationError{Field: "username", Code: "ERR_TOO_SHORT"}\n}\n\nfunc handleRequest() error {\n\tif err := parsePayload(); err != nil {\n\t\treturn fmt.Errorf("http handler failed: %w", err)\n\t}\n\treturn nil\n}\n\nfunc main() {\n\terr := handleRequest()\n\n\tvar valErr *ValidationError\n\tif errors.As(err, &valErr) {\n\t\tfmt.Println("Успешно извлечена структура ValidationError:")\n\t\tfmt.Printf(" -> Поле: %s\\n", valErr.Field)\n\t\tfmt.Printf(" -> Код:  %s\\n", valErr.Code)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Успешно извлечена структура ValidationError:\n#  -> Поле: username\n#  -> Код:  ERR_TOO_SHORT'}], 'under_the_hood': '`errors.As` находит первую ошибку в цепочке, чей тип совместим с типом переменной, переданной по указателю.', 'pitfalls': 'Всегда проверяйте булев результат `if errors.As(err, &target)`. Использование `valErr` без проверки при `false` приведет к nil pointer dereference.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему type assertion err.(*MyError) опасен в современном Go?»\n**Ответ:** Если функция внутри обернет ошибку через `fmt.Errorf("%w")`, `err` перестанет быть `*MyError` (станет `*fmt.wrapError`), и type assertion завершится неудачей или паникой.'}, {'num': 15, 'title': 'Проверка глубоко обернутой ошибки sentinel-типа', 'task': 'Напиши функцию, возвращающую обёрнутую ошибку. В `main` используй `errors.Is(err, target)` для проверки: является ли ошибка (возможно, глубоко обёрнутая) конкретной sentinel-ошибкой.', 'theory': 'Проверка `errors.Is(err, target)` гарантирует корректную работу независимо от того, сколько промежуточных слоев и middleware добавили свои описания в цепочку.', 'step_by_step': '1. Объявим `var ErrUnauthorized = errors.New("unauthorized access")`.\n2. Создадим цепочку из 3 слоев: `AuthService -> Router -> Middleware`.\n3. В `main` проверим `errors.Is(err, ErrUnauthorized)`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n)\n\nvar ErrUnauthorized = errors.New("unauthorized access")\n\nfunc authService() error {\n\treturn ErrUnauthorized\n}\n\nfunc router() error {\n\tif err := authService(); err != nil {\n\t\treturn fmt.Errorf("router auth check: %w", err)\n\t}\n\treturn nil\n}\n\nfunc middleware() error {\n\tif err := router(); err != nil {\n\t\treturn fmt.Errorf("http middleware: %w", err)\n\t}\n\treturn nil\n}\n\nfunc main() {\n\terr := middleware()\n\tfmt.Println("Стек ошибки:", err)\n\n\tif errors.Is(err, ErrUnauthorized) {\n\t\tfmt.Println("Ответ клиенту: HTTP 401 Unauthorized")\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Стек ошибки: http middleware: router auth check: unauthorized access\n# Ответ клиенту: HTTP 401 Unauthorized'}], 'under_the_hood': 'Цепочка вызовов `Unwrap` поднимает маркер наверх без ручного парсинга строк текста ошибки.', 'pitfalls': 'Не сравнивайте текст ошибки через `strings.Contains(err.Error(), "unauthorized")`, это хрупко и приводит к багам при смене локали или текста.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему парсинг текста ошибки через strings.Contains считается грубейшим антипаттерном?»\n**Ответ:** Потому что текст ошибки может измениться при рефакторинге или обновлении сторонней библиотеки, что сломает логику в рантайме без предупреждений компилятора.'}, {'num': 16, 'title': 'Архитектурная цепочка вызовов: readFile -> parseJSON -> validate', 'task': 'Создайте цепочку функций: `readFile -> parseJSON -> validate`. Каждая возвращает ошибку. Пробросьте ошибку вверх, добавив контекст с помощью `fmt.Errorf("...: %w", err)`.', 'theory': 'Каждый уровень абстракции должен отвечать за свой уровень контекста: нижний уровень сообщает о сбое I/O, средний — о сбое парсинга, верхний — о сбое бизнес-валидации.', 'step_by_step': '1. Реализуем `readFile(path string) ([]byte, error)`.\n2. Реализуем `parseJSON(data []byte) (map[string]any, error)`.\n3. Реализуем `validate(m map[string]any) error`.\n4. В `loadConfig` свяжем функции и пробросим ошибки вверх через `%w`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n)\n\nvar ErrFileNotFound = errors.New("file does not exist")\n\nfunc readFile(path string) ([]byte, error) {\n\tif path == "" {\n\t\treturn nil, ErrFileNotFound\n\t}\n\treturn []byte(`{"port": "not_a_number"}`), nil\n}\n\nfunc parseJSON(data []byte) (map[string]any, error) {\n\treturn map[string]any{"port": "invalid"}, nil\n}\n\nfunc validate(cfg map[string]any) error {\n\tif cfg["port"] == "invalid" {\n\t\treturn errors.New("port must be an integer")\n\t}\n\treturn nil\n}\n\nfunc loadConfig(path string) error {\n\tdata, err := readFile(path)\n\tif err != nil {\n\t\treturn fmt.Errorf("loadConfig: reading %q: %w", path, err)\n\t}\n\n\tcfg, err := parseJSON(data)\n\tif err != nil {\n\t\treturn fmt.Errorf("loadConfig: parsing json: %w", err)\n\t}\n\n\tif err := validate(cfg); err != nil {\n\t\treturn fmt.Errorf("loadConfig: validation: %w", err)\n\t}\n\treturn nil\n}\n\nfunc main() {\n\tif err := loadConfig("config.json"); err != nil {\n\t\tfmt.Println("Сбой конфигурации:", err)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Сбой конфигурации: loadConfig: validation: port must be an integer'}], 'under_the_hood': 'Каждый уровень добавляет префикс со своим именем функции, формируя читаемую трассировку.', 'pitfalls': 'Не забывайте выходить из функции `return ...` сразу после получения `err != nil`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как правильно форматировать контекст при оборачивании ошибки?»\n**Ответ:** Шаблон: `<имя_функции_или_действия>: <параметры>: %w`. Например: `fmt.Errorf("fetchUser(id=%d): sending request: %w", id, err)`.'}, {'num': 17, 'title': 'Паттерн повторных попыток (Retry) с экспоненциальной задержкой', 'task': 'Реализуйте паттерн повторных попыток (Retry): если функция вернула определенную ошибку (например, "timeout"), вызовите ее снова до 3 раз с экспоненциальной задержкой.', 'theory': 'Паттерн Retry с экспоненциальным backoff увеличивает задержку между попытками вдвое ($T, 2T, 4T$), снижая нагрузку на восстанавливающуюся систему.', 'step_by_step': '1. Объявим `var ErrTimeout = errors.New("timeout")`.\n2. Реализуем `Retry(attempts int, initialDelay time.Duration, fn func() error) error`.\n3. В цикле вызываем функцию, при `ErrTimeout` удваиваем задержку.\n4. В `main` протестируем успешное восстановление на 3-й попытке.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n\t"time"\n)\n\nvar ErrTimeout = errors.New("request timeout")\n\nfunc Retry(attempts int, delay time.Duration, fn func() error) error {\n\tvar lastErr error\n\tfor i := 1; i <= attempts; i++ {\n\t\terr := fn()\n\t\tif err == nil {\n\t\t\treturn nil\n\t\t}\n\t\tif !errors.Is(err, ErrTimeout) {\n\t\t\treturn err // Non-retryable error\n\t\t}\n\t\tlastErr = err\n\t\tfmt.Printf("Попытка %d не удалась (%v). Ожидание %v...\\n", i, err, delay)\n\t\ttime.Sleep(delay)\n\t\tdelay *= 2 // Экспоненциальный рост\n\t}\n\treturn fmt.Errorf("все %d попыток исчерпаны: %w", attempts, lastErr)\n}\n\nfunc main() {\n\tcount := 0\n\tunstableCall := func() error {\n\t\tcount++\n\t\tif count < 3 {\n\t\t\treturn ErrTimeout\n\t\t}\n\t\treturn nil\n\t}\n\n\terr := Retry(3, 10*time.Millisecond, unstableCall)\n\tif err != nil {\n\t\tfmt.Println("Итоговый сбой:", err)\n\t} else {\n\t\tfmt.Println("Успешно выполнено на попытке:", count)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Попытка 1 не удалась (request timeout). Ожидание 10ms...\n# Попытка 2 не удалась (request timeout). Ожидание 20ms...\n# Успешно выполнено на попытке: 3'}], 'under_the_hood': 'Проверка `errors.Is(err, ErrTimeout)` гарантирует, что мы повторяем только транзиентные (временные) сбои.', 'pitfalls': 'Никогда не делайте retry для фатальных ошибок (например, невалидный пароль или 400 Bad Request).', 'bigtech_interview': '**Вопрос с собеседования:** «Зачем к экспоненциальному backoff добавляют Full Jitter (рандомизацию)?»\n**Ответ:** Без Jitter все параллельные клиенты будут повторять запросы в одни и те же синхронные моменты времени, вызывая повторные волны перегрузки (Thundering Herd Problem). Jitter размывает запросы во времени.'}, {'num': 18, 'title': 'Sentinel-ошибки в нескольких функциях пакета', 'task': 'Создай **sentinel error**: `var ErrNotFound = errors.New("not found")`. Используй её в нескольких функциях. Проверь через `errors.Is` в разных уровнях обёртки.', 'theory': 'Sentinel-ошибки объявляются как пакетные переменные `var Err... = errors.New(...)` и экспортируются для использования другими пакетами.', 'step_by_step': '1. Объявим `var ErrNotFound = errors.New("item not found")`.\n2. Создадим функции `GetProduct(id int)` и `GetCategory(id int)`.\n3. В `main` обработаем результат обеих функций единым блоком `errors.Is`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n)\n\nvar ErrNotFound = errors.New("item not found")\n\nfunc GetProduct(id int) error {\n\tif id <= 0 {\n\t\treturn fmt.Errorf("product repo: %w", ErrNotFound)\n\t}\n\treturn nil\n}\n\nfunc GetCategory(id int) error {\n\tif id <= 0 {\n\t\treturn fmt.Errorf("category repo: %w", ErrNotFound)\n\t}\n\treturn nil\n}\n\nfunc checkItem(name string, fetch func(int) error, id int) {\n\terr := fetch(id)\n\tif errors.Is(err, ErrNotFound) {\n\t\tfmt.Printf("[%s #%d] Объект не найден в системе (HTTP 404)\\n", name, id)\n\t} else if err != nil {\n\t\tfmt.Printf("[%s #%d] Системная ошибка: %v\\n", name, id, err)\n\t} else {\n\t\tfmt.Printf("[%s #%d] Успешно загружен\\n", name, id)\n\t}\n}\n\nfunc main() {\n\tcheckItem("Товар", GetProduct, -1)\n\tcheckItem("Категория", GetCategory, -5)\n\tcheckItem("Товар", GetProduct, 10)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Товар #-1] Объект не найден в системе (HTTP 404)\n# [Категория #-5] Объект не найден в системе (HTTP 404)\n# [Товар #10] Успешно загружен'}], 'under_the_hood': 'Один экземпляр переменной `ErrNotFound` переиспользуется всеми функциями пакета без новых аллокаций.', 'pitfalls': 'Пакетные переменные `var Err...` мутабельны. Ни в коем случае не перезаписывайте их значения в рантайме.', 'bigtech_interview': '**Вопрос с собеседования:** «Как защитить sentinel error от случайной перезаписи из другого пакета?»\n**Ответ:** Использовать кастомный тип константы: `type Error string; func (e Error) Error() string { return string(e) }; const ErrNotFound = Error("not found")`.'}, {'num': 19, 'title': 'Распаковка errors.Is против оператора прямого равенства ==', 'task': '**Распаковка `errors.Is`**: Получив обернутую ошибку из упр. 204, используй `errors.Is(err, ErrNotFound)`, чтобы проверить, есть ли в цепочке обертываний наша маркерная ошибка. (Простое `==` тут уже не сработает).', 'theory': 'При оборачивании ошибки тип переменной меняется со статического `*errors.errorString` на `*fmt.wrapError`. Прямое сравнение указателей `err == ErrNotFound` возвращает `false`.', 'step_by_step': '1. Создадим маркер `var ErrNotFound = errors.New("not found")`.\n2. Обернем его: `wrapped := fmt.Errorf("wrap 1: %w", fmt.Errorf("wrap 2: %w", ErrNotFound))`.\n3. Сравним результаты `wrapped == ErrNotFound` и `errors.Is(wrapped, ErrNotFound)`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n)\n\nvar ErrNotFound = errors.New("not found")\n\nfunc main() {\n\twrapped := fmt.Errorf("api handler: %w", fmt.Errorf("db service: %w", ErrNotFound))\n\n\tfmt.Println("Текст цепочки:", wrapped)\n\n\t// Прямое сравнение:\n\tfmt.Printf("Прямое сравнение (wrapped == ErrNotFound): %v\\n", wrapped == ErrNotFound)\n\n\t// Проверка через errors.Is:\n\tfmt.Printf("Проверка errors.Is(wrapped, ErrNotFound):  %v\\n", errors.Is(wrapped, ErrNotFound))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Текст цепочки: api handler: db service: not found\n# Прямое сравнение (wrapped == ErrNotFound): false\n# Проверка errors.Is(wrapped, ErrNotFound):  true'}], 'under_the_hood': '`errors.Is` разворачивает стек `wrap 1 -> wrap 2 -> ErrNotFound` и находит совпадение по указателю памяти.', 'pitfalls': 'Всегда используйте `errors.Is` вместо `==` при работе с любыми интерфейсами `error`.', 'bigtech_interview': '**Вопрос с собеседования:** «Что возвращает errors.Is(nil, nil)?»\n**Ответ:** `errors.Is(nil, nil)` возвращает `true`. Вызов `errors.Is(err, nil)` возвращает `err == nil`.'}, {'num': 20, 'title': 'Оборачивание системных ошибок ввода-вывода os.Open', 'task': '**Оборачивание ошибок (Wrapping)**: Напишите функцию `ReadFileConfig()`, которая вызывает `os.Open`. Если возникает ошибка, оберните её с помощью `fmt.Errorf("не удалось прочитать конфиг: %w", err)` (используя спецификатор `%w`).', 'theory': 'При вызове стандартных функций ОС (`os.Open`, `net.Dial`) они возвращают системные ошибки (`*os.PathError`). Оборачивание через `%w` сохраняет доступ к исходной системной ошибке.', 'step_by_step': '1. Создадим функцию `ReadFileConfig(path string) ([]byte, error)`.\n2. Вызовем `os.Open(path)`.\n3. Обернем ошибку: `fmt.Errorf("не удалось прочитать конфиг: %w", err)`.\n4. В `main` извлечем `*os.PathError` через `errors.As`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n\t"os"\n)\n\nfunc ReadFileConfig(path string) ([]byte, error) {\n\tfile, err := os.Open(path)\n\tif err != nil {\n\t\treturn nil, fmt.Errorf("не удалось прочитать конфиг: %w", err)\n\t}\n\tdefer file.Close()\n\treturn os.ReadFile(path)\n}\n\nfunc main() {\n\t_, err := ReadFileConfig("/non/existent/config.yaml")\n\tif err != nil {\n\t\tfmt.Println("Ошибка:", err)\n\n\t\tvar pathErr *os.PathError\n\t\tif errors.As(err, &pathErr) {\n\t\t\tfmt.Println("-> Системный сбой ОС:")\n\t\t\tfmt.Printf("   Операция: %s\\n", pathErr.Op)\n\t\t\tfmt.Printf("   Путь:     %s\\n", pathErr.Path)\n\t\t\tfmt.Printf("   Причина:  %v\\n", pathErr.Err)\n\t\t}\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Ошибка: не удалось прочитать конфиг: open /non/existent/config.yaml: no such file or directory\n# -> Системный сбой ОС:\n#    Операция: open\n#    Путь:     /non/existent/config.yaml\n#    Причина:  no such file or directory'}], 'under_the_hood': '`os.Open` возвращает структуру `&os.PathError{Op: "open", Path: path, Err: syscall.ENOENT}`.', 'pitfalls': 'Не забывайте вызывать `defer file.Close()` только после успешной проверки `err == nil`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему defer file.Close() нельзя ставить до проверки if err != nil?»\n**Ответ:** Если `os.Open` вернет ошибку, указатель `file` будет равен `nil`. Вызов `file.Close()` на nil-указателе приведет к немедленной панике (Nil Pointer Dereference).'}, {'num': 21, 'title': 'Агрегация ошибок валидации формы через errors.Join (Go 1.20+)', 'task': 'Изучите функцию `errors.Join` (Go 1.20+), чтобы собрать несколько ошибок, возникших при валидации разных полей формы, в одну агрегированную ошибку.', 'theory': 'Функция `errors.Join(errs ...error) error` объединяет срез ошибок в единое дерево ошибок. Результирующая ошибка форматирует все сообщения через перенос строки `\\n` и реализует метод `Unwrap() []error`.', 'step_by_step': '1. Создадим форму `RegistrationForm` с полями `Email`, `Password`, `Age`.\n2. Напишем валидатор `ValidateForm(f RegistrationForm) error`.\n3. Соберем ошибки в срез и вернем `errors.Join(errs...)`.\n4. В `main` убедимся, что `errors.Is` находит любую из ошибок в объединенном результате.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n\t"strings"\n)\n\nvar (\n\tErrInvalidEmail    = errors.New("некорректный email")\n\tErrPasswordTooWeak = errors.New("пароль должен быть не менее 8 символов")\n\tErrUnderage        = errors.New("возраст должен быть не менее 18 лет")\n)\n\ntype RegistrationForm struct {\n\tEmail    string\n\tPassword string\n\tAge      int\n}\n\nfunc ValidateForm(f RegistrationForm) error {\n\tvar errs []error\n\tif !strings.Contains(f.Email, "@") {\n\t\terrs = append(errs, ErrInvalidEmail)\n\t}\n\tif len(f.Password) < 8 {\n\t\terrs = append(errs, ErrPasswordTooWeak)\n\t}\n\tif f.Age < 18 {\n\t\terrs = append(errs, ErrUnderage)\n\t}\n\treturn errors.Join(errs...)\n}\n\nfunc main() {\n\tform := RegistrationForm{\n\t\tEmail:    "bad-email",\n\t\tPassword: "123",\n\t\tAge:      15,\n\t}\n\n\terr := ValidateForm(form)\n\tif err != nil {\n\t\tfmt.Println("Сводная ошибка валидации:")\n\t\tfmt.Println(err)\n\n\t\t// errors.Is находит каждую отдельную ошибку в Join:\n\t\tfmt.Println("-> Email с ошибкой:", errors.Is(err, ErrInvalidEmail))\n\t\tfmt.Println("-> Пароль слабый: ", errors.Is(err, ErrPasswordTooWeak))\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Сводная ошибка валидации:\n# некорректный email\n# пароль должен быть не менее 8 символов\n# возраст должен быть не менее 18 лет\n# -> Email с ошибкой: true\n# -> Пароль слабый:  true'}], 'under_the_hood': '`errors.Join` фильтрует `nil` элементы и возвращает `nil`, если все аргументы равны `nil`.', 'pitfalls': '`errors.Join` доступен только в Go 1.20+. В старых версиях использовались внешние библиотеки вроде `uber-go/multierr`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как errors.Is проверяет ошибку внутри errors.Join?»\n**Ответ:** `errors.Join` возвращает структуру `joinError`, реализующую метод `Unwrap() []error`. Функция `errors.Is` рекурсивно обходит каждый элемент возвращенного среза.'}, {'num': 22, 'title': 'Извлечение HTTP-кода из кастомной ошибки AppError через errors.As', 'task': '**Извлечение типа `errors.As`**: Оберни свою структуру `AppError` (из упр. 202) через `%w`. В `main` используй `errors.As(err, &myAppErr)`, чтобы достать её из обертки и прочитать конкретный HTTP `Code`.', 'theory': '`errors.As` позволяет слою HTTP-хендлеров централизованно мапить кастомные ошибки доменного слоя в соответствующие HTTP-статус коды (400, 403, 404, 500).', 'step_by_step': '1. Объявим `type AppError struct { HTTPCode int; Message string }`.\n2. Реализуем `(e *AppError) Error() string`.\n3. Создадим цепочку вызовов `DomainService -> HTTPHandler`.\n4. В `main` извлечем `HTTPCode`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n)\n\ntype AppError struct {\n\tHTTPCode int\n\tMessage  string\n}\n\nfunc (e *AppError) Error() string {\n\treturn fmt.Sprintf("HTTP %d: %s", e.HTTPCode, e.Message)\n}\n\nfunc domainLogic() error {\n\treturn &AppError{HTTPCode: 403, Message: "доступ запрещен настройками приватности"}\n}\n\nfunc service() error {\n\tif err := domainLogic(); err != nil {\n\t\treturn fmt.Errorf("service layer: %w", err)\n\t}\n\treturn nil\n}\n\nfunc main() {\n\terr := service()\n\tif err != nil {\n\t\tvar appErr *AppError\n\t\tif errors.As(err, &appErr) {\n\t\t\tfmt.Printf("Отправка клиенту статуса: %d\\n", appErr.HTTPCode)\n\t\t\tfmt.Printf("Тело ответа:             %s\\n", appErr.Message)\n\t\t}\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Отправка клиенту статуса: 403\n# Тело ответа:             доступ запрещен настройками приватности'}], 'under_the_hood': '`errors.As` проверяет типы на соответствие указателю `*AppError` и копирует адрес структуры.', 'pitfalls': 'Передавайте в `errors.As` указатель на указатель `&appErr`, где `var appErr *AppError`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как в production HTTP-серверах реализуют централизованный Error Handler?»\n**Ответ:** Кастомные HTTP-хэндлеры возвращают `error`. Централизованный middleware перехватывает ошибку, через `errors.As` извлекает `*AppError`, выставляет соответствующий HTTP-код, пишет аудит-лог и отправляет JSON клиенту.'}, {'num': 23, 'title': 'Кастомный тип NotFoundError с деталями ресурса и ID', 'task': 'Создай **кастомный тип ошибки** `type NotFoundError struct { Resource string; ID int }`. Реализуй `Error() string`. Используй `errors.As` для извлечения конкретного типа из цепочки ошибок.', 'theory': 'Структурированная ошибка `NotFoundError` точно указывает, какой именно ресурс (`User`, `Order`, `Invoice`) и с каким идентификатором отсутствует.', 'step_by_step': '1. Объявим `type NotFoundError struct { Resource string; ID int }`.\n2. Реализуем `Error() string`.\n3. Создадим функцию `FindUser(id int) error`.\n4. В `main` извлечем `NotFoundError` и выведем форматированное сообщение.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n)\n\ntype NotFoundError struct {\n\tResource string\n\tID       int\n}\n\nfunc (e *NotFoundError) Error() string {\n\treturn fmt.Sprintf("ресурс %s с ID=%d не найден", e.Resource, e.ID)\n}\n\nfunc FindUser(id int) error {\n\treturn fmt.Errorf("user repository: %w", &NotFoundError{Resource: "User", ID: id})\n}\n\nfunc main() {\n\terr := FindUser(777)\n\tif err != nil {\n\t\tvar notFound *NotFoundError\n\t\tif errors.As(err, &notFound) {\n\t\t\tfmt.Printf("Сущность: %s | Идентификатор: %d\\n", notFound.Resource, notFound.ID)\n\t\t}\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Сущность: User | Идентификатор: 777'}], 'under_the_hood': '`NotFoundError` передается по указателю `*NotFoundError`, реализуя контракт `error`.', 'pitfalls': 'Не забывайте, что `NotFoundError` реализует `error` только для указателя `*NotFoundError`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему структурированные ошибки лучше конкатенации строк fmt.Errorf?»\n**Ответ:** Структурированные ошибки позволяют тестировать логику через проверку полей структуры `err.ID == 777` вместо ненадежного сравнения строковых сообщений.'}, {'num': 24, 'title': 'Диспетчеризация sentinel errors через switch и errors.Is', 'task': 'Напиши функцию, возвращающую разные sentinel errors: `ErrInvalidInput`, `ErrNotFound`, `ErrPermissionDenied`. В вызывающем коде используй `switch` с `errors.Is` для разной логики обработки.', 'theory': 'Конструкция `switch` с предикатами `errors.Is` позволяет элегантно маршрутизировать обработку различных бизнес-ошибок.', 'step_by_step': '1. Объявим три sentinel-ошибки: `ErrInvalidInput`, `ErrNotFound`, `ErrPermissionDenied`.\n2. Создадим функцию `executeAction(code int) error`.\n3. В `main` напишем блок `switch` с ветками `case errors.Is(err, ...)`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n)\n\nvar (\n\tErrInvalidInput      = errors.New("invalid input")\n\tErrNotFound          = errors.New("not found")\n\tErrPermissionDenied  = errors.New("permission denied")\n)\n\nfunc executeAction(scenario int) error {\n\tswitch scenario {\n\tcase 1:\n\t\treturn fmt.Errorf("action: %w", ErrInvalidInput)\n\tcase 2:\n\t\treturn fmt.Errorf("action: %w", ErrNotFound)\n\tcase 3:\n\t\treturn fmt.Errorf("action: %w", ErrPermissionDenied)\n\tdefault:\n\t\treturn nil\n\t}\n}\n\nfunc handle(scenario int) {\n\terr := executeAction(scenario)\n\tswitch {\n\tcase errors.Is(err, ErrInvalidInput):\n\t\tfmt.Println("[400 Bad Request] Некорректные параметры запроса")\n\tcase errors.Is(err, ErrNotFound):\n\t\tfmt.Println("[404 Not Found] Запрошенный объект не существует")\n\tcase errors.Is(err, ErrPermissionDenied):\n\t\tfmt.Println("[403 Forbidden] Недостаточно прав для операции")\n\tcase err != nil:\n\t\tfmt.Printf("[500 Internal Error] Непредвиденный сбой: %v\\n", err)\n\tdefault:\n\t\tfmt.Println("[200 OK] Успешное выполнение")\n\t}\n}\n\nfunc main() {\n\thandle(1)\n\thandle(2)\n\thandle(3)\n\thandle(0)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [400 Bad Request] Некорректные параметры запроса\n# [404 Not Found] Запрошенный объект не существует\n# [403 Forbidden] Недостаточно прав для операции\n# [200 OK] Успешное выполнение'}], 'under_the_hood': '`switch` без условия (tagless switch) вычисляет булевы выражения в порядке их объявления сверху вниз.', 'pitfalls': 'Ветка `case err != nil` должна быть предпоследней перед `default`, чтобы перехватывать все остальные непредвиденные ошибки.', 'bigtech_interview': '**Вопрос с собеседования:** «В каком порядке следует проверять ошибки в switch?»\n**Ответ:** От самых специфичных и частых ошибок к более общим, завершая проверкой `case err != nil` для непредвиденных системных сбоев (Catch-all).'}, {'num': 25, 'title': 'Sentinel-ошибка ErrPermissionDenied и проверка вложенности', 'task': '**Проверка ошибок через `errors.Is`**: Объявите глобальную ошибку-маркер (sentinel error) `var ErrPermissionDenied = errors.New("доступ запрещен")`. Напишите функцию, которая глубоко в цепочке вызовов возвращает эту ошибку (обернутую другими ошибками). В функции `main` проверьте наличие этой конкретной ошибки в цепочке с помощью `errors.Is`.', 'theory': 'Sentinel-ошибки безопасности должны надежно определяться на уровне контроллера для возврата клиенту кода `403 Forbidden` вместо `500 Internal Server Error`.', 'step_by_step': '1. Объявим `var ErrPermissionDenied = errors.New("доступ запрещен")`.\n2. Создадим три уровня вложенности вызовов.\n3. В `main` проверим `errors.Is(err, ErrPermissionDenied)`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n)\n\nvar ErrPermissionDenied = errors.New("доступ запрещен")\n\nfunc checkACL(userID int) error {\n\treturn ErrPermissionDenied\n}\n\nfunc secureService(userID int) error {\n\tif err := checkACL(userID); err != nil {\n\t\treturn fmt.Errorf("security check: %w", err)\n\t}\n\treturn nil\n}\n\nfunc apiHandler(userID int) error {\n\tif err := secureService(userID); err != nil {\n\t\treturn fmt.Errorf("api endpoint /admin: %w", err)\n\t}\n\treturn nil\n}\n\nfunc main() {\n\terr := apiHandler(42)\n\tif errors.Is(err, ErrPermissionDenied) {\n\t\tfmt.Println("Безопасность: доступ отклонен (HTTP 403)")\n\t\tfmt.Printf("Полная трассировка: %v\\n", err)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Безопасность: доступ отклонен (HTTP 403)\n# Полная трассировка: api endpoint /admin: security check: доступ запрещен'}], 'under_the_hood': '`errors.Is` раскручивает стек вызовов без выделения дополнительной памяти.', 'pitfalls': 'Не маскируйте ошибки прав доступа под общую ошибку базы данных.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в микросервисах важно мапить ErrPermissionDenied в HTTP 403 / gRPC PermissionDenied?»\n**Ответ:** Чтобы клиентское приложение понимало причину отказа (ошибка авторизации) и не запускало бессмысленные автоматические повторы (Retry Storm).'}, {'num': 26, 'title': 'Создание кастомного типа ошибки с методом Error() string', 'task': 'Создай кастомный тип ошибки (структуру, реализующую метод `Error() string`).', 'theory': 'Кастомная ошибка может содержать подробные системные характеристики: временную метку `time.Time`, хост `Host`, операцию `Op`.', 'step_by_step': '1. Объявим `type QueryError struct { Query string; DurationMs int64; Err error }`.\n2. Реализуем `(e *QueryError) Error() string` и `(e *QueryError) Unwrap() error`.\n3. В `main` выведем ошибку.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n)\n\ntype QueryError struct {\n\tQuery      string\n\tDurationMs int64\n\tErr        error\n}\n\nfunc (e *QueryError) Error() string {\n\treturn fmt.Sprintf("запрос %q упал за %d мс: %v", e.Query, e.DurationMs, e.Err)\n}\n\nfunc (e *QueryError) Unwrap() error {\n\treturn e.Err\n}\n\nfunc executeSlowQuery() error {\n\treturn &QueryError{\n\t\tQuery:      "SELECT count(*) FROM big_table",\n\t\tDurationMs: 5200,\n\t\tErr:        errors.New("statement timeout exceeded"),\n\t}\n}\n\nfunc main() {\n\terr := executeSlowQuery()\n\tif err != nil {\n\t\tfmt.Println("Лог ошибки:", err)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Лог ошибки: запрос "SELECT count(*) FROM big_table" упал за 5200 мс: statement timeout exceeded'}], 'under_the_hood': 'Метод `Unwrap() error` позволяет `QueryError` поддерживать нативную интеграцию с `errors.Is`/`errors.As`.', 'pitfalls': 'Если структура оборачивает другую ошибку, всегда реализуйте метод `Unwrap() error`.', 'bigtech_interview': '**Вопрос с собеседования:** «Зачем кастомной структуре ошибки реализовывать метод Unwrap() error?»\n**Ответ:** Без метода `Unwrap()` стандартные функции `errors.Is` и `errors.As` не смогут заглянуть внутрь вашей структуры и найти вложенную первопричину (`Err`).'}, {'num': 27, 'title': 'Паттерн Guard Clauses: ранний возврат и плоская структура кода', 'task': 'Напиши функцию с **guard clauses**: функция выполняет 3 проверки (валидация входных данных, проверка существования файла, проверка прав). Каждая проверка — `if err != nil { return ..., err }`. Избегай вложенных `if/else`.', 'theory': 'Паттерн Guard Clauses (защитные условия) устраняет "лесенку" вложенных блоков `if-else`, делая код плоским, линейным и простым для чтения.', 'step_by_step': '1. Создадим функцию `ProcessDocument(user string, docID string, data []byte) error`.\n2. Реализуем 3 последовательных проверки с немедленным выходом при ошибке.\n3. В `main` протестируем обработку.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n)\n\nfunc validateInput(user, docID string) error {\n\tif user == "" || docID == "" {\n\t\treturn errors.New("пользователь и ID документа обязательны")\n\t}\n\treturn nil\n}\n\nfunc checkPermissions(user string) error {\n\tif user == "guest" {\n\t\treturn errors.New("гостевым пользователям запрещено редактирование")\n\t}\n\treturn nil\n}\n\nfunc verifyPayload(data []byte) error {\n\tif len(data) == 0 {\n\t\treturn errors.New("документ не может быть пустым")\n\t}\n\treturn nil\n}\n\nfunc ProcessDocument(user, docID string, data []byte) error {\n\t// Guard 1: Проверка входных аргументов\n\tif err := validateInput(user, docID); err != nil {\n\t\treturn fmt.Errorf("guard validate: %w", err)\n\t}\n\n\t// Guard 2: Проверка прав доступа\n\tif err := checkPermissions(user); err != nil {\n\t\treturn fmt.Errorf("guard perms: %w", err)\n\t}\n\n\t// Guard 3: Проверка тела документа\n\tif err := verifyPayload(data); err != nil {\n\t\treturn fmt.Errorf("guard payload: %w", err)\n\t}\n\n\t// Основная логика (Happy Path):\n\tfmt.Printf("Документ %s успешно обработан для %s (%d байт)\\n", docID, user, len(data))\n\treturn nil\n}\n\nfunc main() {\n\tif err := ProcessDocument("guest", "doc-1", []byte("data")); err != nil {\n\t\tfmt.Println("Сбой:", err)\n\t}\n\n\tif err := ProcessDocument("admin", "doc-2", []byte("Hello Go")); err != nil {\n\t\tfmt.Println("Сбой:", err)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Сбой: guard perms: гостевым пользователям запрещено редактирование\n# Документ doc-2 успешно обработан для admin (8 байт)'}], 'under_the_hood': 'Guard clauses минимизируют цикломатическую сложность (Cyclomatic Complexity) функции.', 'pitfalls': 'Не оборачивайте успешную часть в `else { ... }`. После блока `if err != nil { return err }` код продолжается на основном уровне отступа.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Go сообществе избегают конструкции if err == nil { ... } else { return err }?»\n**Ответ:** Потому что это инвертирует логику, сдвигает успешный путь вправо и заставляет разработчика держать в голове контекст вложенности вместо чтения функции сверху вниз.'}, {'num': 28, 'title': 'Объединение ошибок цикла валидации через errors.Join', 'task': '**Множественные ошибки (Join)**: В цикле валидации данных у тебя накопилось 3 разных ошибки. Используй `errors.Join(err1, err2, err3)` (Go 1.20+), чтобы склеить их в одну ошибку, и выведи её.', 'theory': 'Сбор нескольких независимых ошибок в цикле с последующим вызовом `errors.Join(errs...)` позволяет вернуть клиенту исчерпывающий список всех некорректных строк за один запрос.', 'step_by_step': '1. Создадим срез строк `records`.\n2. В цикле проверим каждую запись и соберем ошибки.\n3. Объединим ошибки через `errors.Join`.\n4. В `main` выведем отчет об ошибках.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n\t"strconv"\n)\n\nfunc validateRows(rows []string) error {\n\tvar errList []error\n\tfor i, row := range rows {\n\t\tif _, err := strconv.Atoi(row); err != nil {\n\t\t\terrList = append(errList, fmt.Errorf("строка %d (%q): не является числом", i+1, row))\n\t\t}\n\t}\n\treturn errors.Join(errList...)\n}\n\nfunc main() {\n\tbatch := []string{"100", "invalid_num", "300", "another_bad_val", "500"}\n\n\terr := validateRows(batch)\n\tif err != nil {\n\t\tfmt.Println("Ошибки пакетной обработки:")\n\t\tfmt.Println(err)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Ошибки пакетной обработки:\n# строка 2 ("invalid_num"): не является числом\n# строка 4 ("another_bad_val"): не является числом'}], 'under_the_hood': '`errors.Join` форматирует ошибки через разделитель `\\n`, сохраняя строковую структуру отчета.', 'pitfalls': 'Если список `errList` пуст, `errors.Join(errList...)` безопасно вернет `nil`.', 'bigtech_interview': '**Вопрос с собеседования:** «Что вернет errors.Join() без аргументов или со всеми nil?»\n**Ответ:** `errors.Join()` без аргументов или если все переданные элементы равны `nil` вернет строго литерал `nil`.'}, {'num': 29, 'title': 'Перехват критической паники через defer и recover на верхнем уровне', 'task': 'Напишите функцию, которая вызывает `panic` при критическом сбое, и используйте `defer` + `recover` на верхнем уровне (`main` или HTTP-хендлере), чтобы перехватить панику и превратить ее в обычный лог или HTTP 500.', 'theory': '`panic` останавливает нормальное выполнение горутины, раскручивая стек и выполняя `defer`-функции. Функция `recover()` останавливает панику и возвращает значение, переданное в `panic()`.', 'step_by_step': '1. Создадим функцию `riskyOperation()`, вызывающую `panic("непредвиденный сбой драйвера")`.\n2. Создадим middleware `safeHandler()`, содержащий `defer func() { if r := recover(); r != nil { ... } }()`.\n3. В `main` вызовем `safeHandler()` и убедимся, что процесс не упал.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"runtime/debug"\n)\n\nfunc riskyOperation() {\n\t// Симуляция критического сбоя\n\tpanic("критическая ошибка: обращение к неинициализированной памяти")\n}\n\nfunc safeHandler() {\n\tdefer func() {\n\t\tif r := recover(); r != nil {\n\t\t\tfmt.Printf("[RECOVER] Перехвачена паника: %v\\n", r)\n\t\t\tfmt.Println("[RECOVER] Ответ клиенту: HTTP 500 Internal Server Error")\n\t\t\tfmt.Printf("[STACKTRACE]:\\n%s\\n", string(debug.Stack()))\n\t\t}\n\t}()\n\n\tfmt.Println("Старт обработки запроса...")\n\triskyOperation()\n\tfmt.Println("Запрос обработан успешно (не будет напечатано)")\n}\n\nfunc main() {\n\tsafeHandler()\n\tfmt.Println("Сервер продолжает стабильную работу после перехвата паники!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Старт обработки запроса...\n# [RECOVER] Перехвачена паника: критическая ошибка: обращение к неинициализированной памяти\n# [RECOVER] Ответ клиенту: HTTP 500 Internal Server Error\n# [STACKTRACE]:\n# ...\n# Сервер продолжает стабильную работу после перехвата паники!'}], 'under_the_hood': '`recover()` возвращает ненулевое значение только при вызове напрямую внутри функции, запущенной через `defer`.', 'pitfalls': 'Паника, возникшая в фоновой горутине `go func()`, НЕ может быть перехвачена `recover()` в родительской горутине! Каждая горутина обязана иметь свой собственный `recover`.', 'bigtech_interview': '**Вопрос с собеседования:** «Может ли recover() в main горутине поймать панику в фоновой go func()?»\n**Ответ:** Нет! Паника изолирована в рамках конкретной горутины. Неперехваченная паника в любой горутине немедленно аварийно завершает весь процесс приложения.'}]
